const cab = (eyebrow, titulo, sub = "", acoes = "") => `<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${titulo}</h1>${sub ? `<p class="muted">${sub}</p>` : ""}</div>${acoes ? `<div class="heading-actions">${acoes}</div>` : ""}</section>`;
const vazio = (t, txt = "", link = "", rot = "") => `<div class="empty-state"><span class="ico-tile lg tom-blush">${ic("heart", 26)}</span><h3>${t}</h3>${txt ? `<p>${txt}</p>` : ""}${link ? `<a class="button button-light" href="${link}">${rot}</a>` : ""}</div>`;
const badgeA = (s) => `<span class="badge badge-at-${slug(s)}">${esc(s)}</span>`, badgeP = (s) => `<span class="badge badge-pg-${slug(s)}">${esc(s)}</span>`;
const opts = (arr, sel) => arr.map((o) => { const [v, r] = Array.isArray(o) ? o : [o, o]; return `<option value="${esc(v)}" ${String(v) === String(sel) ? "selected" : ""}>${esc(r)}</option>`; }).join("");
const grafico = (titulo, d, alt = 220) => `<div class="chart-card panel"><div class="panel-heading"><h2>${titulo}</h2></div>${d.values.some((v) => v) ? `<div class="chart" role="img" aria-label="Gráfico: ${titulo}" data-chart='${chartAttr(d)}' style="height:${alt}px"></div>` : '<p class="chart-empty muted">Sem dados neste período.</p>'}</div>`;
const PROX = { Agendado: "Confirmar", Confirmado: "Iniciar", "Em atendimento": "Concluir" };

function cartao(a, volta = "") {
  const op = [];
  if (pode("agenda.gravar") || pode("agenda.andamento")) { const p = Ag.FLUXO[a.status_atendimento]; if (p && (pode("agenda.gravar") || ["Em atendimento", "Realizado"].includes(p))) op.push(`<button class="act-btn act-primary" data-status="${a.id}:${p}">${PROX[a.status_atendimento]}</button>`); }
  if (pode("agenda.gravar") && !["Cancelado", "Falta", "Realizado"].includes(a.status_atendimento)) op.push(`<button class="act-btn" data-status="${a.id}:Falta">Falta</button><button class="act-btn act-danger" data-status="${a.id}:Cancelado" data-conf="Cancelar este atendimento?">Cancelar</button>`);
  if (pode("agenda.gravar")) op.push(`<a class="act-btn" href="#/atendimento/${a.id}/editar">Editar / remarcar</a>`);
  if (pode("pagamentos.gravar") && a.saldo > 0 && !["Cancelado", "Falta"].includes(a.status_atendimento)) op.push(`<a class="act-btn" href="#/atendimento/${a.id}/pagamento">Pagamento</a>`);
  return `<article class="appt appt-${slug(a.status_atendimento)}"><div class="appt-time"><strong>${a.horario_agendado}</strong><span>até ${a.fim}</span><small>${a.duracao_min || 60} min</small></div>
  <div class="appt-main"><a class="appt-client" href="#/atendimento/${a.id}">${esc(a.cliente_nome)}</a><span class="appt-service">${esc(a.servico)}${volta === "data" ? " · " + dataBR(a.data) : ""}</span><div class="appt-badges">${badgeA(a.status_atendimento)} ${badgeP(a.status_pagamento)}</div></div>
  <div class="appt-money"><strong>${moeda(a.valor_centavos)}</strong>${a.saldo > 0 && a.status_pagamento !== "Cancelado" ? `<small>A receber ${moeda(a.saldo)}</small>` : ""}</div>
  <div class="appt-actions">${op.join("")}</div></article>`;
}
function ligarStatus(raiz, recarregar) {
  raiz.addEventListener("click", async (e) => { const b = e.target.closest("[data-status]"); if (!b) return; if (b.dataset.conf && !(await confirmar(b.dataset.conf))) return; const [id, st] = b.dataset.status.split(":"); b.disabled = true;
    try { await Ag.mudarStatus(+id, st); toast("Situação atualizada."); await recarregar(); } catch (err) { toast(err.message, "erro"); b.disabled = false; } });
}
export async function buscaGlobal(q) {
  const nq = norm(q), dq = q.replace(/\D/g, ""), r = [];
  if (pode("clientes.ler")) for (const c of await ler("clientes")) if (norm(c.nome).includes(nq) || (dq.length >= 3 && c.telefone.replace(/\D/g, "").includes(dq))) r.push({ rotulo: c.nome, detalhe: "Cliente · " + c.telefone, url: `#/cliente/${c.id}` });
  if (pode("servicos.ler")) for (const s of await ler("servicos")) if (norm(s.nome).includes(nq)) r.push({ rotulo: s.nome, detalhe: "Serviço", url: "#/servicos" });
  if (pode("agenda.ler")) { const cs = new Map((await ler("clientes")).map((c) => [c.id, c.nome])); for (const a of (await ler("atendimentos")).slice().reverse()) if (norm(a.servico).includes(nq) || norm(cs.get(a.cliente_id) || "").includes(nq)) { r.push({ rotulo: `${cs.get(a.cliente_id)} — ${a.servico}`, detalhe: `Atendimento · ${dataBR(a.data)} ${a.horario_agendado}`, url: `#/atendimento/${a.id}` }); if (r.length > 12) break; } }
  if (pode("despesas.gravar")) for (const d of await ler("despesas")) if (norm(d.descricao).includes(nq)) r.push({ rotulo: d.descricao, detalhe: "Despesa · " + reais(d.valor_centavos), url: "#/despesas" });
  return r.slice(0, 10);
}
