  const cfg = await config(), livres = await Ag.livres(h, cfg.agenda_inicio, cfg.agenda_fim);
  const verFin = pode("financeiro.ler"), m = verFin ? await Fin.resumo(h, h) : null, previsto = ativos.reduce((s, a) => s + a.valor_centavos, 0);
  const proximo = ativos.find((a) => ["Agendado", "Confirmado"].includes(a.status_atendimento) && a.horario_agendado >= hh), atras = ativos.filter((a) => ["Agendado", "Confirmado"].includes(a.status_atendimento) && a.horario_agendado < hh);
