  const perfis = pode("clientes.ler") ? await Cli.listar() : [], mmdd = h.slice(5), aniv = perfis.filter((p) => p.data_nascimento && p.data_nascimento.slice(5) === mmdd);
  const r30 = perfis.filter((p) => p.dias_sem_visita != null && p.dias_sem_visita >= 30 && !p.proximo).length, vip = perfis.filter((p) => p.tags.includes("VIP") && !p.proximo).length;
