rota(/^(painel|)$/, async (_, q) => {
  if (!pode("financeiro.ler")) return { redirecionar: "#/hoje" };
  const ch = q.get("p") || "30dias"; const [i, f] = periodo(ch, q.get("de"), q.get("ate")), r = await Fin.resumo(i, f);
  const dias = []; for (let d = i; d <= f && dias.length < 62; d = somarDias(d, 1)) dias.push(d);
  const html = cab("PAINEL DE CONTROLE", "Como está o salão", "Tudo calculado a partir dos registros neste dispositivo.") +
    `<div class="period-filter panel"><div class="period-chips">${PERIODOS.map(([k, n]) => `<a class="chip${ch === k ? " active" : ""}" href="#/painel?p=${k}">${n}</a>`).join("")}</div></div>
    <div class="kpi-grid"><div class="kpi kpi-accent"><div class="card-head"><span class="stat-label">Recebido</span>${tile("trend", "ink", 20)}</div><strong>${moeda(r.recebido)}</strong></div><div class="kpi"><div class="card-head"><span class="stat-label">Despesas</span>${tile("receipt", "sand", 20)}</div><strong>${moeda(r.despesas)}</strong></div><div class="kpi"><div class="card-head"><span class="stat-label">Resultado</span>${tile("wallet", "wine", 20)}</div><strong>${moeda(r.lucro)}</strong></div><div class="kpi kpi-warn"><div class="card-head"><span class="stat-label">A receber</span>${tile("alert", "sand", 20)}</div><strong>${moeda(r.aReceber)}</strong><span class="stat-note">${r.pendentes} pendência(s)</span></div>
    <div class="kpi"><div class="card-head"><span class="stat-label">Atendimentos</span>${tile("calendar", "blush", 20)}</div><strong>${r.atendimentos}</strong><span class="stat-note">${r.realizados} realizados · ${r.cancelados} cancel. · ${r.faltas} faltas</span></div><div class="kpi"><div class="card-head"><span class="stat-label">Ticket médio</span>${tile("star", "rose", 20)}</div><strong>${moeda(r.ticket)}</strong></div></div>
    <div class="chart-grid"><div class="chart-wide">${grafico("Recebido por dia", { labels: dias.map((d) => d.slice(8) + "/" + d.slice(5, 7)), values: dias.map((d) => r.porDia[d] || 0), kind: "bar", money: true })}</div>${grafico("Formas de pagamento", { labels: Object.keys(r.porForma), values: Object.values(r.porForma), kind: "donut", money: true })}</div>`;
  return { html };
});
