rota(/^agenda$/, async (_, q) => {
  const sel = q.get("data") || hojeISO(), modo = q.get("modo") || "dia", st = q.get("situacao") || "";
  let de = sel, ate = sel, ant, prox;
  if (modo === "semana") { const dt = new Date(sel + "T12:00:00"); de = somarDias(sel, -((dt.getDay() + 6) % 7)); ate = somarDias(de, 6); ant = somarDias(sel, -7); prox = somarDias(sel, 7); }
  else if (modo === "lista") { ate = somarDias(sel, 60); ant = somarDias(sel, -60); prox = somarDias(sel, 60); } else { ant = somarDias(sel, -1); prox = somarDias(sel, 1); }
  const lista = await Ag.listar({ de, ate, status: st }), L = (m) => `#/agenda?modo=${m}&data=${sel}`;
  let corpo;
  if (modo === "semana") { const dias = [...Array(7)].map((_, k) => somarDias(de, k));
    corpo = `<div class="week-grid">${dias.map((d) => { const l = lista.filter((a) => a.data === d); return `<section class="panel week-col${d === hojeISO() ? " is-today" : ""}"><header><a href="#/agenda?modo=dia&data=${d}"><span class="eyebrow">${diaSemana(d)}</span><strong>${dataBR(d).slice(0, 5)}</strong></a><span class="calendar-count">${l.length}</span></header>${l.map((a) => `<a class="week-appt" href="#/atendimento/${a.id}"><strong>${a.horario_agendado}–${a.fim}</strong>${esc(a.cliente_nome)}<small>${esc(a.servico)}</small>${badgeA(a.status_atendimento)}</a>`).join("") || `<a class="week-empty" href="#/atendimento/novo?data=${d}">${ic("plus", 18)} livre</a>`}</section>`; }).join("")}</div>`; }
  else corpo = lista.length ? `<section class="panel"><div class="appt-list" id="lista-ag">${lista.map((a) => cartao(a, modo === "lista" ? "data" : "")).join("")}</div></section>` : `<section class="panel">${vazio("Nenhum atendimento neste período", "", "#/atendimento/novo?data=" + sel, `${ic("plus", 18)} Adicionar agendamento`)}</section>`;
  const cfg = await config(), livres = modo === "dia" ? await Ag.livres(sel, cfg.agenda_inicio, cfg.agenda_fim) : [];
  const html = cab("ORGANIZAÇÃO DOS HORÁRIOS", "Agenda", `${diaSemana(sel)}, ${dataBR(sel)}`, pode("agenda.gravar") ? `<a class="button" href="#/atendimento/novo?data=${sel}">${ic("plus", 18)} Novo agendamento</a>` : "") +
    `<div class="agenda-bar panel"><div class="agenda-date-nav"><a class="button button-light" href="#/agenda?modo=${modo}&data=${ant}" aria-label="Anterior">←</a><input type="date" id="agenda-data" value="${sel}" aria-label="Data"><a class="button button-light" href="#/agenda?modo=${modo}&data=${prox}" aria-label="Próximo">${ic("right", 16)}</a><a class="text-link" href="#/agenda?modo=${modo}">Hoje</a></div>
    <div class="segmented">${[["dia", "Dia"], ["semana", "Semana"], ["lista", "Lista"]].map(([k, n]) => `<a class="${modo === k ? "active" : ""}" href="${L(k)}">${n}</a>`).join("")}</div>
    <select id="agenda-sit" aria-label="Situação"><option value="">Todas as situações</option>${opts(Ag.STATUS, st)}</select></div>
    <p class="agenda-summary muted">${lista.length} atendimento(s) · ${lista.filter((a) => a.status_atendimento === "Realizado").length} realizado(s) · ${lista.filter((a) => a.status_atendimento === "Cancelado").length} cancelado(s)</p>` +
    (livres.length ? `<div class="free-slots"><span class="muted">Horários livres:</span>${livres.map((l) => `<a class="chip" href="#/atendimento/novo?data=${sel}&inicio=${l[0]}">${l[0]}–${l[1]}</a>`).join("")}</div>` : "") + corpo;
  return { html, depois: (el, rec) => { ligarStatus(el, rec); el.querySelector("#agenda-data").onchange = (e) => (location.hash = `#/agenda?modo=${modo}&data=${e.target.value}`); el.querySelector("#agenda-sit").onchange = (e) => (location.hash = `#/agenda?modo=${modo}&data=${sel}&situacao=${encodeURIComponent(e.target.value)}`); } };
});
