rota(/^privacidade$/, async () => {
  const d = await Bkp.diagnostico(), mb = (n) => (n == null ? "indisponível" : n > 1048576 ? (n / 1048576).toFixed(1) + " MB" : (n / 1024).toFixed(0) + " KB");
  const html = cab("PRIVACIDADE E DADOS", "Privacidade e dados", "<strong>Seus dados são armazenados neste dispositivo.</strong> Nada é enviado para servidores.") + `<section class="panel panel-pad"><dl class="facts"><div><dt>Tamanho aproximado do banco</dt><dd>${mb(d.uso)}${d.quota ? ` de ${mb(d.quota)} disponíveis` : ""}</dd></div><div><dt>Clientes</dt><dd>${d.cont.clientes}</dd></div><div><dt>Atendimentos</dt><dd>${d.cont.atendimentos}</dd></div><div><dt>Último backup baixado</dt><dd>${d.ultimoDownload || "nunca"}</dd></div><div><dt>Última cópia automática</dt><dd>${d.ultimoSnapshot || "nenhuma"}</dd></div><div><dt>Armazenamento protegido contra limpeza automática</dt><dd>${d.persistente == null ? "não informado" : d.persistente ? "sim" : "não (o navegador pode limpar se faltar espaço)"}</dd></div></dl><button class="button button-light" id="pedir-persist">Pedir armazenamento persistente</button></section>
  <section class="panel panel-pad"><h2>O que isto significa</h2><ul class="plain-list"><li>Se você limpar os “dados do site” ou o cache do navegador, ou desinstalar o app, <strong>os dados deste aparelho podem ser apagados</strong>. O backup é a forma de recuperar.</li><li>Em modo privado/anônimo os dados não persistem.</li><li>No iPhone/iPad, o Safari pode apagar dados de sites não usados por ~7 dias; instalar na Tela de Início reduz esse risco.</li></ul></section>`;
  return { html, depois: (el) => (el.querySelector("#pedir-persist").onclick = async () => { const ok = navigator.storage?.persist ? await navigator.storage.persist() : false; toast(ok ? "Armazenamento persistente concedido." : "O navegador não concedeu. Continue fazendo backups.", ok ? "sucesso" : "aviso"); }) };
});
rota(/^config$/, async () => {
  const c = await config();
  const html = cab("PERSONALIZAÇÃO", "Configurações") + `<form class="panel form-panel" id="f-cfg"><div class="form-grid"><label class="field">Nome do salão<input name="nome_sistema" required maxlength="40" value="${esc(c.nome_sistema)}"></label><label class="field">Cor principal<input type="color" name="cor_principal" value="${c.cor_principal}"></label><label class="field">Tema<select name="tema">${opts([["claro", "Claro"], ["escuro", "Escuro"]], c.tema)}</select></label><label class="field">Expediente — início<input type="time" name="agenda_inicio" value="${c.agenda_inicio}"></label><label class="field">Expediente — fim<input type="time" name="agenda_fim" value="${c.agenda_fim}"></label><label class="field">Bloquear após (min sem uso; 0 desativa)<input type="number" name="bloqueio_minutos" min="0" max="720" value="${c.bloqueio_minutos}"></label><label class="field check-field"><span><input type="checkbox" name="backup_automatico" ${c.backup_automatico === "1" ? "checked" : ""}> Backup automático diário neste aparelho</span></label></div><div class="form-actions"><button class="button" type="submit">Salvar</button></div></form>
  <section class="panel panel-pad"><h2>Sistema</h2><dl class="facts"><div><dt>Salão.gestão</dt><dd>Versão ${esc(INFO.versao)} · ${dataBR(INFO.data)}</dd></div></dl><div class="form-actions"><a class="button" href="#/manutencao">${ic("wrench", 18)} Manutenção</a><a class="button button-light" href="#/diagnostico" id="cfg-diag">${ic("pulse", 18)} Diagnóstico</a><a class="button button-light" href="#/sobre">${ic("info", 18)} Sobre</a></div></section>`;
  return { html, depois: (el) => ligarForm("#f-cfg", async (d) => { if (!/^#[0-9a-f]{6}$/i.test(d.cor_principal)) throw new Error("Cor inválida."); const bm = +d.bloqueio_minutos; if (!(bm >= 0 && bm <= 720)) throw new Error("Bloqueio: 0 a 720 minutos."); if (d.agenda_inicio >= d.agenda_fim) throw new Error("O fim do expediente deve ser depois do início.");
    for (const k of ["nome_sistema", "cor_principal", "tema", "agenda_inicio", "agenda_fim", "bloqueio_minutos"]) await definirConfig(k, d[k]); await definirConfig("backup_automatico", d.backup_automatico ? "1" : "0");
    await transacao(["auditoria"], "readwrite", (t) => auditar(t, "edicao", "configuracao", null, "Configurações alteradas")); toast("Configurações salvas."); location.reload(); }, el) };
});
rota(/^usuarios$/, async () => {
  const l = await Usr.listar();
  const html = cab("ACESSO NESTE DISPOSITIVO", "Usuários", "O administrador tem acesso total. Perfis limitados protegem contra uso casual neste aparelho.") + `<form class="panel form-panel" id="f-usr"><h2 class="form-section-title">Novo usuário</h2><div class="form-grid"><label class="field">Nome<input name="nome" required maxlength="60"></label><label class="field">Usuário<input name="usuario" required maxlength="30" autocapitalize="none"></label><label class="field">Perfil<select name="perfil"><option value="recepcao">Recepção (agenda, clientes, atendimentos, pagamentos)</option><option value="funcionario">Funcionário (ver agenda e clientes; andamento)</option></select></label><label class="field">Senha (mín. 8)<input type="password" name="senha" required minlength="8" autocomplete="new-password"></label></div><div class="form-actions"><button class="button" type="submit">Criar usuário</button></div></form>
  <section class="panel"><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Nome</th><th>Usuário</th><th>Perfil</th><th>Situação</th><th></th></tr></thead><tbody>${l.map((u) => `<tr class="${u.ativo ? "" : "is-inactive"}"><td data-label="Nome"><strong>${esc(u.nome)}</strong></td><td data-label="Usuário">${esc(u.usuario)}</td><td data-label="Perfil">${u.perfil}</td><td data-label="Situação">${u.ativo ? "Ativo" : "Desativado"}</td><td class="row-actions">${u.perfil !== "admin" ? `<button class="text-link" data-alt="${u.id}">${u.ativo ? "Desativar" : "Ativar"}</button><button class="text-link" data-senha="${u.id}">Redefinir senha</button>` : ""}</td></tr>`).join("")}</tbody></table></div></section>`;
  return { html, depois: (el, rec) => { ligarForm("#f-usr", async (d) => { await Usr.criar(d); toast("Usuário criado."); rec(); }, el); el.querySelectorAll("[data-alt]").forEach((b) => (b.onclick = async () => { try { await Usr.alternar(+b.dataset.alt); rec(); } catch (e) { toast(e.message, "erro"); } })); el.querySelectorAll("[data-senha]").forEach((b) => (b.onclick = async () => { const s = await pedir("Redefinir senha", { rotulo: "Nova senha (mín. 8 caracteres)", tipo: "password", minlength: 8, ok: "Redefinir" }); if (s) try { await Usr.redefinirSenha(+b.dataset.senha, s); toast("Senha redefinida."); } catch (e) { toast(e.message, "erro"); } })); } };
});
rota(/^minha-senha$/, async () => ({ html: cab("CONTA", "Minha senha") + `<form class="panel form-panel" id="f-ms"><div class="form-grid"><label class="field field-full">Senha atual<input type="password" name="a" required></label><label class="field">Nova senha (mín. 8)<input type="password" name="n" required minlength="8"></label></div><div class="form-actions"><button class="button" type="submit">Alterar</button></div></form>`, depois: (el) => ligarForm("#f-ms", async (d) => { await Usr.alterarMinhaSenha(d.a, d.n); toast("Senha alterada."); location.hash = "#/hoje"; }, el) }));
rota(/^auditoria$/, async (_, q) => {
  const todos = (await ler("auditoria")).sort((a, b) => b.id - a.id), pag = +q.get("pag") || 0, l = todos.slice(pag * 40, pag * 40 + 40);
  return { html: cab("HISTÓRICO", "Auditoria", `${todos.length} evento(s)`) + `<section class="panel"><ul class="audit-list">${l.map((x) => `<li><time>${esc(x.quando)}</time><span class="audit-act">${esc(x.acao)}</span><span>${esc(x.resumo)} <em>${esc(x.usuario)}</em></span></li>`).join("") || "<li>Nada registrado.</li>"}</ul></section><div class="pager">${pag ? `<a class="button button-light" href="#/auditoria?pag=${pag - 1}">${ic("left", 16)} Anteriores</a>` : "<span></span>"}${(pag + 1) * 40 < todos.length ? `<a class="button button-light" href="#/auditoria?pag=${pag + 1}">Mais antigos ${ic("right", 16)}</a>` : ""}</div>` };
});
rota(/^instalar$/, async () => ({ html: cab("COMO UM APLICATIVO", "Instalar Salão.gestão", "Instalado, abre pelo ícone, em janela própria, e funciona sem internet. Seus dados ficam neste dispositivo.") +
  `<section class="panel panel-pad" id="instalar-agora" hidden><h2>Este navegador pode instalar agora</h2><button class="button" id="botao-instalar">Instalar aplicativo</button></section><div class="detail-grid"><section class="panel panel-pad"><h2>Android (Chrome)</h2><ol class="plain-list"><li>Abra o endereço do Salão.gestão no Chrome (precisa de internet só nesta primeira vez).</li><li>Toque em <em>Instalar aplicativo</em> acima, ou menu ⋮ ${ic("right", 16)} <em>Instalar app</em> / <em>Adicionar à tela inicial</em>.</li><li>Abra pelo ícone. Pode usar em modo avião.</li></ol></section><section class="panel panel-pad"><h2>iPhone / iPad (Safari)</h2><ol class="plain-list"><li>Abra no <strong>Safari</strong>.</li><li>Compartilhar ${ic("right", 16)} <em>Adicionar à Tela de Início</em>.</li><li>Abra pelo ícone criado. Instalado, o iOS protege melhor os dados do que no navegador comum.</li></ol></section><section class="panel panel-pad"><h2>Windows / Mac / Linux</h2><ol class="plain-list"><li>Chrome ou Edge: ícone de instalar na barra de endereços (ou menu ${ic("right", 16)} <em>Instalar Salão.gestão</em>).</li><li>Safari no Mac: Arquivo ${ic("right", 16)} <em>Adicionar ao Dock</em>.</li></ol></section><section class="panel panel-pad"><h2>Estado</h2><dl class="facts"><div><dt>Modo</dt><dd id="est-modo">…</dd></div><div><dt>Funciona offline</dt><dd id="est-sw">…</dd></div><div><dt>Armazenamento</dt><dd>IndexedDB neste aparelho</dd></div></dl><p><a class="button button-light" href="#/diagnostico">${ic("pulse", 18)} Diagnóstico da instalação</a></p></section></div>`,
  depois: (el) => { const bi = el.querySelector("#botao-instalar"), box = el.querySelector("#instalar-agora"); if (window.__promptInstalar) box.hidden = false;
    bi.onclick = async () => { const p = window.__promptInstalar; if (!p) return; window.__promptInstalar = null; box.hidden = true; // o pedido do navegador só pode ser usado uma vez
      try { await p.prompt(); const r = await p.userChoice; Diag.marcarInstalacao(r.outcome === "accepted" ? "aceita" : "recusada"); toast(r.outcome === "accepted" ? "Instalando… o ícone aparece quando o Android concluir. Se não aparecer, abra o Diagnóstico." : "Instalação cancelada."); }
      catch (e) { toast("Não foi possível abrir a instalação: " + e.message, "erro"); } }; el.querySelector("#est-modo").textContent = matchMedia("(display-mode: standalone)").matches || navigator.standalone ? "Instalado (janela própria)" : "No navegador"; navigator.serviceWorker?.getRegistration().then((r) => (el.querySelector("#est-sw").textContent = r?.active ? "Sim — abre mesmo sem internet" : "Ainda não ativo (recarregue a página)")); } }));

// ============================ DIAGNÓSTICO (11.1) — Configurações › Sistema › Diagnóstico ============================
const DIAG = { ok: ["insight-positivo", "check", "badge-pg-pago", "OK"], aviso: ["insight-atencao", "alert", "badge-pg-pendente", "Atenção"], erro: ["insight-erro", "x", "badge-at-falta", "Falha"] };
rota(/^diagnostico$/, async () => {
  const d = await Diag.executar(), nErro = d.itens.filter((i) => i.estado === "erro").length, nAviso = d.itens.filter((i) => i.estado === "aviso").length;
  const html = cab("CONFIGURAÇÕES › SISTEMA", "Diagnóstico", "Confere neste aparelho o que o Android precisa para instalar o Salão.gestão e usar sem internet. Só leitura: nada é alterado.", `<a class="button button-light" href="#/config">${ic("left", 16)} Configurações</a>`) +
  `<section class="panel diag"><div class="panel-heading"><h2>PWA</h2><span class="badge ${nErro ? "badge-at-falta" : nAviso ? "badge-pg-pendente" : "badge-pg-pago"}" id="d-resumo">${nErro ? nErro + " falha(s)" : nAviso ? nAviso + " aviso(s)" : "Tudo certo"}</span></div>
   <ul class="insights diag-list">${d.itens.map((i) => `<li class="insight ${DIAG[i.estado][0]}" data-diag="${i.id}" data-estado="${i.estado}"><span aria-hidden="true">${ic(DIAG[i.estado][1], 16)}</span><div><strong>${esc(i.titulo)}</strong> <span class="badge ${DIAG[i.estado][2]}">${DIAG[i.estado][3]}</span><br>${esc(i.texto)}${i.detalhe ? `<br><small class="muted">${esc(i.detalhe)}</small>` : ""}</div></li>`).join("")}</ul></section>
  <div class="form-actions"><button class="button" type="button" id="d-again">${ic("refresh", 18)} Verificar novamente</button><button class="button button-light" type="button" id="d-copy">${ic("list", 18)} Copiar relatório</button><a class="button button-light" href="#/instalar">${ic("download", 18)} Instalar app</a></div>
  <pre class="diag-relatorio" id="d-rel" hidden></pre>
  <div class="detail-grid"><section class="panel panel-pad diag"><h2>Ambiente</h2><dl class="facts"><div><dt>Versão</dt><dd>${esc(d.versao)}</dd></div><div><dt>Endereço</dt><dd>${esc(d.endereco)}</dd></div><div><dt>Identidade do app</dt><dd>${esc(d.identidade)}</dd></div><div><dt>Navegador</dt><dd>${esc(d.nav.nome)} · ${esc(d.nav.so)}</dd></div><div><dt>Modo</dt><dd>${d.modo === "browser" ? "Navegador" : "Aplicativo (" + esc(d.modo) + ")"} · ${d.online ? "online" : "offline"}</dd></div></dl></section>
  <section class="panel panel-pad"><h2>Se a instalação não concluir</h2><ol class="plain-list"><li>Use o <strong>Chrome</strong> atualizado. Outros navegadores no Android costumam criar só um atalho.</li><li>Atualize o <strong>Google Play Store</strong> e o <strong>Google Play Services</strong>: é por eles que o Android instala o app gerado pelo Chrome.</li><li>Confira o espaço livre e se o <strong>Play Protect</strong> não bloqueou a instalação.</li><li>Xiaomi, Redmi e POCO: permita ao Chrome <em>Atalhos na tela inicial</em> (Configurações, Apps, Chrome, Outras permissões).</li><li>Se existir um ícone antigo ou uma instalação pela metade, remova-o, reinicie o celular e tente de novo.</li><li><strong>Nunca</strong> use "Limpar dados" do site ou do Chrome sem antes exportar um backup: isso apaga os dados deste aparelho.</li></ol></section></div>`;
  return { html, depois: (el, rec) => {
    el.querySelector("#d-again").onclick = () => rec();
    el.querySelector("#d-copy").onclick = async () => { const texto = Diag.relatorio(d), pre = el.querySelector("#d-rel");
      try { await navigator.clipboard.writeText(texto); toast("Relatório copiado. Ele não contém dados de clientes."); } catch (_) { pre.textContent = texto; pre.hidden = false; toast("Selecione e copie o relatório exibido abaixo."); } };
  } };
});

// ============================ MANUTENÇÃO / SOBRE (10.1) ============================
const mb = (n) => (n == null ? "indisponível" : n > 1048576 ? (n / 1048576).toFixed(1) + " MB" : (n / 1024).toFixed(0) + " KB");
const passo = (ok, t) => `<li class="${ok ? "ok" : ""}"><strong>${ok ? ic("check", 16) : "…"}</strong> ${t}</li>`;
rota(/^manutencao$/, async () => {
  const e = await Man.estado(), vs = await Man.versoesDisponiveis();
  // 11.3.1: a lista reflete a regra de retorno (a mesma do service worker): versão bloqueada aparece sem botão, com o motivo
  const retorno = new Map(await Promise.all(vs.filter((v) => !v.ativa && !v.fixada).map(async (v) => [v.versao, await Man.podeVoltarPara(v.versao).catch((err) => ({ ok: false, motivo: err.message }))])));
  const motivoCurto = (m) => { const f = String(m || "").split(/(?<=\.)\s+/)[0]; return f ? f.charAt(0).toLowerCase() + f.slice(1) : ""; };
  const html = cab("SISTEMA", "Manutenção", "Backup, restauração e atualização segura. Atualizar o aplicativo nunca apaga os seus dados.", `<a class="button button-light" href="#/config">${ic("left", 16)} Configurações</a>`) +
  `<div class="kpi-grid"><div class="kpi kpi-accent"><span class="stat-label">Versão instalada</span><strong class="kpi-text">${esc(e.versao)}</strong><span class="stat-note">de ${dataBR(e.data)}</span></div>
   <div class="kpi"><span class="stat-label">Armazenamento</span><strong class="kpi-text">IndexedDB ativo</strong><span class="stat-note">estrutura v${e.banco} · dados v${esc(e.schemaGravado)} · ${e.persistente ? "protegido" : "não persistente"}</span></div>
   <div class="kpi"><span class="stat-label">PWA</span><strong class="kpi-text">${e.pwa.offlinePronto ? "Offline pronto" : esc(e.pwa.sw)}</strong><span class="stat-note">${e.pwa.instalado ? "instalado" : "no navegador"} · ${e.pwa.online ? "online" : "offline"}</span></div>
   <div class="kpi ${e.ultimoDownload ? "" : "kpi-warn"}"><span class="stat-label">Último backup</span><strong class="kpi-text">${e.ultimoDownload ? esc(e.ultimoDownload.slice(0, 16)) : "nunca baixado"}</strong><span class="stat-note">cópia automática: ${e.ultimoSnapshot ? esc(e.ultimoSnapshot.criado_em.slice(0, 16)) : "—"}</span></div>
   <div class="kpi"><span class="stat-label">Espaço utilizado</span><strong class="kpi-text">${mb(e.uso)}</strong><span class="stat-note">${e.cont.clientes} clientes · ${e.cont.atendimentos} atendimentos</span></div></div>${alertaTamanho(tamanhoCopia(e.ultimoSnapshot))}
  <section class="panel panel-pad"><h2>Ações</h2><div class="quick-actions">
   <button class="qa" id="m-exp">${tile("download", "rose", 20)}<span>Exportar backup</span></button><label class="qa">${tile("upload", "wine", 20)}<span>Importar backup</span><input type="file" id="m-arq" accept=".salaobackup,.json" hidden></label>
   <button class="qa" id="m-app">${tile("package", "sand", 20)}<span>Exportar aplicação</span></button><button class="qa" id="m-comp">${tile("database", "blush", 20)}<span>Criar backup completo</span></button>
   <button class="qa" id="m-ver">${tile("refresh", "rose", 20)}<span>Verificar atualização</span></button><button class="qa" id="m-rest">${tile("wrench", "wine", 20)}<span>Restaurar dados</span></button><a class="qa" href="#/sobre">${tile("info", "sand", 20)}<span>Informações da aplicação</span></a></div>
   <div class="legend"><p><strong>Backup de dados (.salaobackup)</strong> ${ic("right", 16)} preserva clientes, agenda, financeiro, usuários e configurações.</p><p><strong>Backup da aplicação (.zip)</strong> ${ic("right", 16)} preserva os arquivos do programa. <em>Não contém seus dados.</em></p><p><strong>Backup completo (.zip)</strong> ${ic("right", 16)} os dois juntos: pasta <code>app/</code> + <code>data/backup.salaobackup</code>.</p></div></section>
  <div id="m-res"></div><div id="previa"></div><div id="m-restaurar"></div>
  <div class="detail-grid"><section class="panel panel-pad"><h2>Versões disponíveis</h2>${vs.length ? `<ul class="mini-list">${vs.map((v) => { const p = retorno.get(v.versao), bloqueada = !v.ativa && !v.fixada && !(p && p.ok);
    return `<li><div><strong>${esc(v.versao)}</strong>${v.ativa ? " · em uso" : ""}${v.fixada ? " · fixada" : ""}<small>${esc(v.cache)}</small>${bloqueada ? `<small data-retorno-bloqueado="${esc(v.versao)}">Não pode ser usada para retorno seguro${p && p.motivo ? ": " + esc(motivoCurto(p.motivo)) : "."}</small>` : ""}</div>${v.fixada || (!v.ativa && !bloqueada) ? `<button class="act-btn" data-voltar="${esc(v.versao)}">${v.fixada ? "Usar a mais recente" : "Voltar para esta"}</button>` : ""}</li>`; }).join("")}</ul>` : '<p class="muted">Disponível quando o aplicativo estiver instalado para uso offline.</p>'}<p class="foot-note muted">Voltar de versão é não destrutivo: só troca os arquivos do programa; seus dados não são alterados. Um backup é criado antes.</p></section>
  <section class="panel panel-pad"><h2>Backups disponíveis</h2>${e.snapshots.length ? `<ul class="mini-list">${e.snapshots.map((b) => `<li><div>${esc(rotuloCopia(b))}<small>${esc(b.criado_em)} · ${(tamanhoCopia(b) / 1024).toFixed(0)} KB</small></div><button class="text-link" data-snap="${b.id}">Baixar</button></li>`).join("")}</ul>` : '<p class="muted">Nenhuma cópia local ainda.</p>'}${e.snapshots.some((b) => b.motivo === "pre_importacao") ? `<p><a class="text-link" href="#/desfazer">Desfazer a última restauração</a></p>` : ""}</section></div>
  <section class="panel panel-pad"><h2>Migrations</h2><p class="muted">Estrutura nativa v${e.banco} · dados v${esc(e.schemaGravado)} (esperado v${e.schema}). Histórico: ${e.migracoes.length ? e.migracoes.map((m) => `#${m.migration} ${m.direcao}`).join(", ") : "nenhuma executada neste aparelho"}.</p></section>`;
  return { html, depois: (el, rec) => {
    const res = el.querySelector("#m-res"), ocupado = async (b, fn) => { b.disabled = true; try { await fn(); } catch (err) { toast(err.message, "erro"); res.innerHTML = `<div class="alert erro">${esc(err.message)}</div>`; } finally { b.disabled = false; } };
    el.querySelector("#m-exp").onclick = (ev) => ocupado(ev.currentTarget, async () => { const r = await Bkp.baixar(); if (r.consistente) { toast("Backup criado e validado. Guarde o arquivo em local seguro."); await rec(); avisarTamanho(r.bytes); } else res.innerHTML = `<div class="alert aviso"><div><strong>Backup gerado com atenção.</strong> ${esc(AVISO_INCONSISTENTE)}<ul class="plain-list">${r.problemas.map((p) => `<li>${esc(p)}</li>`).join("")}</ul></div></div>${alertaTamanho(r.bytes)}`; });
    el.querySelector("#m-app").onclick = (ev) => ocupado(ev.currentTarget, async () => { const r = await Man.exportarAplicacao(); res.innerHTML = `<div class="alert aviso">${ic("check", 16)} ${esc(r.nome)} gerado (${r.arquivos} arquivos). É o backup do <strong>programa</strong>; seus dados não estão nele.</div>`; });
    el.querySelector("#m-comp").onclick = (ev) => ocupado(ev.currentTarget, async () => { const r = await Man.backupCompleto(); res.innerHTML = `<div class="alert aviso">${ic("check", 16)} ${r.consistente === false ? `<span>Backup completo gerado: aplicação + ${r.contagens.clientes} cliente(s), ${r.contagens.atendimentos} atendimento(s). Senhas só como hash. <strong>Atenção:</strong> ${esc(AVISO_INCONSISTENTE)}</span>` : `Backup completo gerado: aplicação + ${r.contagens.clientes} cliente(s), ${r.contagens.atendimentos} atendimento(s). Senhas só como hash.`}</div>${alertaTamanho(r.bytes)}`; if (r.consistente !== false) { await rec(); avisarTamanho(r.bytes); } });
    el.querySelector("#m-arq").onchange = async (ev) => { const f = ev.target.files[0]; if (!f) return; limparPrevia(el, "Verificando o arquivo…");
      try { await mostrarPrevia(el, await Rst.analisarArquivo(f), f.name); }
      catch (err) { limparPrevia(el); falhou("Não foi possível verificar o arquivo (nada foi alterado)", err); }
      finally { ev.target.value = ""; } };
    el.querySelector("#m-rest").onclick = () => { const box = el.querySelector("#m-restaurar"); box.innerHTML = `<section class="panel panel-pad"><h2>Restaurar dados</h2><p class="muted">Escolha uma cópia deste aparelho ou um arquivo. Você verá o resumo e confirmará; antes de substituir, um backup de segurança dos dados atuais é criado e validado.</p>${e.snapshots.length ? `<ul class="mini-list">${e.snapshots.map((b) => `<li><div>${esc(rotuloCopia(b))}<small>${esc(b.criado_em)}</small></div><button class="act-btn" data-rest="${b.id}">Restaurar esta</button></li>`).join("")}</ul>` : ""}<label class="field">Ou escolha um arquivo<input type="file" id="m-arq2" accept=".salaobackup,.json"></label></section>`;
      box.querySelectorAll("[data-rest]").forEach((b) => (b.onclick = async () => { limparPrevia(el, "Abrindo a cópia…");
        try { await mostrarPrevia(el, await Bkp.validar(await textoDaCopia(+b.dataset.rest)), "cópia local"); el.querySelector("#previa").scrollIntoView(); }
        catch (err) { limparPrevia(el); falhou("Não foi possível abrir a cópia para restaurar (nada foi alterado)", err); } }));
      box.querySelector("#m-arq2").onchange = async (ev) => { const f = ev.target.files[0]; if (!f) return; limparPrevia(el, "Verificando o arquivo…");
        try { await mostrarPrevia(el, await Rst.analisarArquivo(f), f.name); el.querySelector("#previa").scrollIntoView(); }
        catch (err) { limparPrevia(el); ev.target.value = ""; falhou("Não foi possível verificar o arquivo (nada foi alterado)", err); } }; };
    el.querySelectorAll("[data-snap]").forEach((b) => (b.onclick = async () => {
      try { const t = await Bkp.snapshotTexto(+b.dataset.snap); if (typeof t !== "string") throw new Error("essa cópia não existe mais neste aparelho (pode ter sido substituída por uma mais nova). Atualize a tela."); Bkp.baixarTexto(t, Bkp.nomeArquivo()); }
      catch (err) { falhou("Não foi possível baixar a cópia", err); } }));
    el.querySelector("#m-ver").onclick = (ev) => ocupado(ev.currentTarget, async () => {
      res.innerHTML = '<p class="muted">Verificando…</p>'; const r = await Man.verificarAtualizacao();
      if (r.erro) { res.innerHTML = `<div class="alert aviso">${esc(r.erro)}</div>`; return; }
      if (!r.disponivel && !r.aguardando) { res.innerHTML = `<div class="alert aviso">${ic("check", 16)} Você já está na versão mais recente (${esc(r.atual)}).</div>`; return; }
      res.innerHTML = `<section class="panel panel-pad"><h2>Nova versão disponível</h2><dl class="facts"><div><dt>Atual</dt><dd>${esc(r.atual)}</dd></div><div><dt>Nova</dt><dd>${esc(r.nova)}</dd></div></dl><p><strong>Alterações:</strong></p><ul class="plain-list">${r.alteracoes.map((a) => `<li>${esc(a)}</li>`).join("")}</ul><p class="muted">Antes de atualizar será criado e validado um backup. Se o backup falhar, a atualização não continua.</p><ul class="plain-list" id="m-passos"></ul><div class="form-actions"><button class="button" id="m-atualizar">Atualizar agora</button><button class="button button-light" id="m-depois">Mais tarde</button></div></section>`;
      res.querySelector("#m-depois").onclick = () => (res.innerHTML = "");
      res.querySelector("#m-atualizar").onclick = (e2) => ocupado(e2.currentTarget, async () => { const ps = res.querySelector("#m-passos"); const log = [];
        await Man.aplicarAtualizacao((fase, b) => { if (fase === "backup") log.push(passo(false, "Criando backup automático…")); if (fase === "backup-ok") { log.length = 0; log.push(passo(true, "Backup automático criado"), passo(true, "Validado"), passo(true, `Dados preservados (${b.preservados.clientes} clientes, ${b.preservados.atendimentos} atendimentos)`), "<li><strong>Agora é seguro continuar.</strong></li>"); } if (fase === "baixando") log.push(passo(false, "Instalando a nova versão em segundo plano…")); if (fase === "ativando") log.push(passo(true, "Ativando — o aplicativo vai recarregar")); ps.innerHTML = log.join(""); }); }); });
    el.querySelectorAll("[data-voltar]").forEach((b) => (b.onclick = () => ocupado(b, async () => { if (b.textContent.includes("mais recente")) { await Man.usarMaisRecente(); } else { if (!(await confirmar(`Voltar para a versão ${b.dataset.voltar}? Seus dados não serão alterados; um backup será criado antes.`, { perigo: false, titulo: "Voltar de versão" }))) return; await Man.voltarVersao(b.dataset.voltar); } toast("Versão trocada. Recarregando…"); setTimeout(() => location.reload(), 600); })));
  } };
});
rota(/^sobre$/, async () => {
  const e = await Man.estado(), reg = await navigator.serviceWorker?.getRegistration(), vs = await Man.versoesDisponiveis();
  const html = cab("INFORMAÇÕES", "Sobre o Salão.gestão", "Gestão de salão que funciona neste dispositivo. Seus dados não saem dele.") +
  `<section class="panel panel-pad"><dl class="facts"><div><dt>Sistema</dt><dd>${esc(INFO.sistema)}</dd></div><div><dt>Versão</dt><dd><strong>${esc(INFO.versao)}</strong> (${dataBR(INFO.data)})</dd></div><div><dt>Estrutura do banco (IndexedDB)</dt><dd>v${e.banco} · migrations de dados v${esc(e.schemaGravado)}/${e.schema}</dd></div><div><dt>Formato de backup</dt><dd>.salaobackup v1 · compatibilidade com backups 9.x não verificada</dd></div><div><dt>Service worker</dt><dd>${esc(e.pwa.sw)}${reg?.scope ? " · escopo " + esc(reg.scope) : ""}</dd></div><div><dt>Cache em uso</dt><dd>${esc(vs.find((v) => v.ativa)?.cache || "—")}</dd></div><div><dt>Arquivos do programa</dt><dd>${INFO.arquivos.length}</dd></div><div><dt>Modo</dt><dd>${e.pwa.instalado ? "Instalado (standalone)" : "Navegador"} · ${e.pwa.online ? "online" : "offline"}</dd></div><div><dt>Navegador</dt><dd>${esc(navigator.userAgent.slice(0, 90))}</dd></div></dl></section>
  <section class="panel panel-pad"><h2>Novidades desta versão</h2><ul class="plain-list">${INFO.alteracoes.map((a) => `<li>${esc(a)}</li>`).join("")}</ul></section><p><a class="button" href="#/manutencao">${ic("wrench", 18)} Abrir Manutenção</a></p>`;
  return { html };
});
